function writePage(url,title,description,body,active='',schema=null) {
  const originalUrl=url;
  const configKey=originalUrl.match(/^\/calculators\/([^/]+)\/$/)?.[1];
  seoConfiguration[configKey];
  url=routeAliases[originalUrl]||originalUrl;
  const canonical=origin+url;
  const headTitle=seoConfiguration[configKey]?.seoTitle||(url==='/'?'Hourly Wage Converter | Free Hourly to Salary Calculator':`${title} | Hourly Wage Converter`);
  description=seoConfiguration[configKey]?.description||description;
  const graph=schema?(schema['@graph']||[schema]).map(item=>{const {'@context':context,...rest}=item;return rest;}):[];
  if(url!=='/'){
    const list=[{'@type':'ListItem',position:1,name:'Home',item:origin+'/'}];
    const group=seoConfiguration[configKey]?'calculators':url.split('/').filter(Boolean).length>1?url.split('/')[1]:null;
    if(group)list.push({'@type':'ListItem',position:2,name:{calculators:'Calculators',hourly:'Hourly guides',salary:'Salary guides',articles:'Articles',author:'Author'}[group]||group,item:origin+`/${group}/`});
    list.push({'@type':'ListItem',position:list.length+1,name:title,item:canonical});
    graph.push({'@type':'BreadcrumbList',itemListElement:list});
  }
  if(url==='/'){
    graph.push({'@type':'WebApplication',name:'Hourly Wage Converter',applicationCategory:'UtilitiesApplication',operatingSystem:'Any',browserRequirements:'Requires JavaScript'});
    graph.push({
      '@type':'Organization',
      name:'Hourly Wage Converter',
      url:origin+'/',
      logo:origin+'/favicon.svg',
      sameAs:[
        'https://www.youtube.com/@hourlywageconverter',
        'https://www.instagram.com/hourlywageconverter/',
        'https://www.reddit.com/user/hourlywageconverter/',
        'https://www.facebook.com/hourlywageconverter'
      ]
    });
  }
  const schemaValue=graph.length?{'@context':'https://schema.org','@graph':graph}:null;
  const pageImage=graph.find(i=>i['@type']==='Article')?.image;
  const isArticle=graph.some(i=>i['@type']==='Article');
  const ogImage=pageImage||(url==='/'?canonical.replace(/\/$/,'')+'/assets/images/hourly-wage-salary-guide-featured.jpg':'https://hourlywageconverter.com/assets/images/og-default.jpg');

  const html=`<!doctype html><html lang="en"><head><meta charset="utf-8">${gtagScript}<meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(headTitle)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${canonical}"><meta name="theme-color" content="#ee3524"><meta name="google-site-verification" content="7JdOxJb6uYOPHz1CR_a-6fVKwjsh3U8WQXOOF-ZrC4U"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="${isArticle?'article':'website'}"><meta property="og:url" content="${canonical}">${ogImage?`<meta property="og:image" content="${ogImage}"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="675">`:''}<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="${esc(title)}"><meta name="twitter:description" content="${esc(description)}">${ogImage?`<meta name="twitter:image" content="${ogImage}">`:''}<link rel="icon" type="image/svg+xml" href="data:image/svg+xml,${favicon}"><link rel="icon" type="image/svg+xml" href="/favicon.svg?v=3"><link rel="icon" href="/favicon.ico?v=3" sizes="any"><link rel="apple-touch-icon" href="/favicon.svg?v=3"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="/assets/styles.css?v=3.15">${schemaValue?`<script type="application/ld+json">${JSON.stringify(schemaValue).replaceAll('<','\\u003c')}</script>`:''}<script type="module" src="/assets/app.js?v=3.2"></script></head><body class="font-['Poppins',_sans-serif] bg-slate-50 text-slate-900">${header(active)}<main id="main" class="wrap">${body}</main>${footer()}</body></html>`;
  const dir=path.join(root,url);fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,'index.html'),remapLinks(html));routes.push({url,title});
}
const pageHead=(title,desc,eyebrow='Wage & salary tools',direct=false)=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p${direct?' class="direct-answer"':''}>${direct?`<span class="direct-answer-label">Direct Answer</span>`:''}${desc}</p></div><div class="head-badge">${icon('shield',16)} Gross pay estimates</div></div>`;
