const field=(name,label,value,{prefix='',suffix='',helper='',min='0',max='',step='any',large=false}={})=>`<label class="field${large?' large':''}"><span>${label}</span><span class="input-wrap${prefix?' has-prefix':''}${suffix?' has-suffix':''}">${prefix?`<span class="prefix">${prefix}</span>`:''}<input name="${name}" id="${name}" type="number" value="${value}" min="${min}"${max?` max="${max}"`:''} step="${step}" inputmode="decimal" required>${suffix?`<span class="suffix">${suffix}</span>`:''}</span>${helper?`<span class="helper">${helper}</span>`:''}</label>`;
const select=(name,label,options,value)=>`<label class="field"><span>${label}</span><select name="${name}" id="${name}">${options.map(([val,text])=>`<option value="${val}"${value===val?' selected':''}>${text}</option>`).join('')}</select></label>`;
