const directionSwitch=(period)=>`<div class="mode-switch" role="group" aria-label="Pay basis"><button type="button" data-direction="hourly" aria-pressed="${period==='hourly'}">Hourly pay</button><button type="button" data-direction="annual" aria-pressed="${period==='annual'}">Annual salary</button></div>`;
