function converterForm({period='hourly',amount=25,kind='converter',primary='annual',slug=''}={}) {
 return `<form class="card form-card sticky" data-calculator="converter" data-primary="${primary}" ${slug?'':`data-auto-direction="true"`} novalidate><div class="card-header"><h2>Your pay & schedule</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div>${directionSwitch(period)}<div class="pay-top">${field('amount',period==='annual'?'Annual salary':'Hourly wage',amount,{prefix:'$',large:true,suffix:period==='annual'?'/ year':'/ hour'})}</div>${presets(hourlyPresets,'amount','hourly')}${presets(salaryPresets,'amount','annual')}<details class="more-periods"><summary>Other pay periods ${icon('chevron',14)}</summary>${select('period','Input pay period',periodOptions,period)}</details><div class="form-section"><h3>Work schedule</h3><div class="fields">${field('hoursWeek','Regular hours per week',40,{max:168,min:.01,step:.5})}${field('weeks','Weeks per year',52,{max:52,min:.01,step:1,helper:'Before any unpaid weeks below.'})}</div></div><details class="advanced"><summary><span>Advanced options</span>${icon('chevron',17)}</summary><div class="fields">${field('days','Days per week',5,{max:7,min:.01,step:.5})}${field('unpaid','Unpaid weeks off',0,{max:51.99,step:1})}${field('overtimeHours','Overtime hours / week',0,{max:168,step:.5})}${field('multiplier','Overtime multiplier',1.5,{min:.01,step:.25,suffix:'×'})}</div><p class="caption">Paid weeks = weeks per year − unpaid weeks. Overtime hours are extra.</p></details>${formButtons(primary==='hourly'?'Calculate hourly rate':'Calculate wage')}${regularFormFoot}</form>`;
}
const payBar=(title,segs,total)=>{
 const shown=segs.filter(s=>s[2]>0);
 if(!(total>0)||!shown.length)return '';
 const bar=shown.map(s=>`<div class="pay-bar-seg ${s[0]}" style="width:${(s[2]/total*100).toFixed(2)}%" title="${s[1]}"></div>`).join('');
 const legend=shown.map(s=>`<div class="pay-legend-row"><span class="pay-legend-dot ${s[0]}"></span><span>${s[1]}</span><strong>${money(s[2])}</strong></div>`).join('');
 return `<div class="pay-breakdown-title">${title}</div><div class="pay-bar" aria-hidden="true">${bar}</div><div class="pay-legend">${legend}</div>`;
};
const resultCell=(key,label,value)=>`<div class="result-cell"><span class="result-label">${label}</span><strong class="result-value" data-out="${key}">${key==='percent'?`${value.toFixed(2)}%`:['billableHours','totalHours'].includes(key)?value.toLocaleString('en-US'):money(value)}</strong></div>`;
function converterResults(config={}) {
 const defaults={period:'hourly',amount:25,hours:8,days:5,weeks:52,unpaid:0,...config};
 const r=convert(defaults);const primary=config.primary||'annual';
 const label=primary==='hourly'?'Your equivalent hourly rate':primary==='biweekly'?'Your gross paycheck':'Your annual gross pay';
 const annualFocus=primary==='annual';
 const cells=annualFocus?[['monthly','Monthly'],['weekly','Weekly'],['biweekly','Biweekly'],['semimonthly','Semi-monthly'],['hourly','Hourly'],['daily','Daily']]:[['annual','Annual'],['monthly','Monthly'],['weekly','Weekly'],['biweekly','Biweekly'],['semimonthly','Semi-monthly'],['hourly','Hourly'],['daily','Daily']];
 return `<aside class="result-card sticky" aria-label="Pay conversion results" data-results><div class="result-heading"><div class="result-topline"><span data-primary-label>${label}</span><span class="result-tag">BEFORE TAX</span></div><div class="result-amount"><span data-out="primary">${money(r[primary])}</span><small data-primary-unit>${primary==='hourly'?'/ hour':primary==='biweekly'?'/ check':'/ year'}</small></div><div class="result-assumption" data-assumption>40 hours/week · 52 paid weeks/year</div></div><div class="result-grid">${cells.map(([k,l])=>resultCell(k,l,r[k]).replace('<div class=\"result-cell\"',`<div ${k===(primary==='hourly'?'annual':'hourly')?'data-base-period-cell':''} class=\"result-cell\"`)).join('')}</div><div class="adjusted-result"><span>Estimated take-home · annual (federal only)</span><strong data-out="takeHomeAnnual">${money(r.takeHomeAnnual)}</strong></div><div class="adjusted-result"><span>Estimated take-home · monthly</span><strong data-out="takeHomeMonthly">${money(r.takeHomeMonthly)}</strong></div><div class="adjusted-result"><span>Estimated take-home · biweekly</span><strong data-out="takeHomeBiweekly">${money(r.takeHomeBiweekly)}</strong></div><p class="caption">Single filer · 2026 federal brackets ($16,100 standard deduction) + FICA. State tax, benefits, and exact W-4 withholding excluded.</p><div class="pay-breakdown" data-breakdown>${payBar("Where your annual pay goes",[["seg-takehome","Take-home",r.takeHomeAnnual],["seg-federal","Federal tax",r.federalTax],["seg-fica","FICA",r.ficaTax]],r.annual)}</div><div class="micro-results"><div><span>Per minute</span><strong data-out="minute">${money(r.minute,3)}</strong></div><div><span>Per second</span><strong data-out="second">${money(r.second,4)}</strong></div><div><span>Quarterly</span><strong data-out="quarterly">${money(r.quarterly)}</strong></div></div><div class="milestones" data-milestones></div><div class="result-note"><strong>${salaryHint}</strong><br><span data-result-note>Monthly and semi-monthly figures are annual averages.</span></div>${resultActions()}<span class="sr-only" data-live aria-live="polite" aria-atomic="true"></span></aside>`;
}
