function overtimeTool() {
 const init=overtime({rate:25,regular:40,extra:10,multiplier:1.5,weeks:52});
 return `<div class="tool-layout"><form class="card form-card sticky" data-calculator="overtime" novalidate><div class="card-header"><h2>Your hours & rate</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div>${field('rate','Regular hourly rate',25,{prefix:'$',large:true})}${presets([15,20,25,30,40,50],'rate','overtime')}<div class="form-section"><div class="fields">${field('regular','Regular hours / week',40,{max:168,step:.5})}${field('extra','Overtime hours / week',10,{max:168,step:.5})}${select('multiplierMode','Overtime multiplier',[['1.25','1.25×'],['1.5','1.5× · time and a half'],['2','2× · double time'],['custom','Custom multiplier']],'1.5')}${select('otMode','Overtime rule',[['weekly','Weekly rule · over 40 hours'],['daily','Daily rule · CA-style (8h/day)']],'weekly')}<div data-daily-fields hidden>${field('hoursPerDay','Hours per day',10,{max:24,min:.01,step:.5})}${field('daysPerWeek','Days per week',5,{max:7,min:1,step:1})}</div>${field('weeks','Paid weeks / year',52,{max:52,min:.01,step:1})}<div data-custom-multiplier hidden>${field('multiplier','Custom multiplier',1.5,{min:.01,step:.25,suffix:'×'})}</div></div><div class="presets"><button type="button" class="preset" data-multiplier="1.5">1.5× Time and a half</button><button type="button" class="preset" data-multiplier="2">2× Double time</button></div></div>${formButtons('Calculate overtime pay')}${regularFormFoot}</form>${resultPanel('Your overtime hourly rate','overtimeRate','/ hour',[['regularPay','Regular weekly pay'],['overtimePay','Overtime weekly pay'],['totalHours','Total weekly hours'],['total','Total weekly gross pay'],['annualOvertime','Annual overtime earnings'],['annual','Annual total gross pay']],init,`<strong>${salaryHint}</strong><br>Regular and overtime hours are entered separately. Eligibility is not determined by this calculator.`,'40 regular + 10 overtime hours/week').replace('<span class="sr-only"',`${resultActions()}<span class="sr-only"`)}</div>`;
}
function paycheckTool() {
 const config={period:'hourly',amount:25,hoursWeek:40,weeks:52,overtimeHours:0,multiplier:1.5,payFrequency:'biweekly',bonus:0,preTax:0,postTax:0,otherDeductions:0};
 const init=paycheck(config);
 const form=`<form class="card form-card sticky" data-calculator="paycheck" novalidate><div class="card-header"><h2>Your paycheck details</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div>${directionSwitch('hourly')}<div class="sr-only">${select('period','Pay basis',[['hourly','Hourly pay'],['annual','Annual salary']],'hourly')}</div>${field('amount','Hourly wage',25,{prefix:'$',large:true,suffix:'/ hour'})}${presets([15,20,25,30,40,50],'amount','hourly')}${presets(salaryPresets,'amount','annual')}<div class="form-section"><div class="fields">${field('hoursWeek','Regular hours / week',40,{min:.01,max:168,step:.5})}${select('payFrequency','Pay frequency',[['weekly','Weekly · 52 checks'],['biweekly','Biweekly · 26 checks'],['semimonthly','Semi-monthly · 24 checks'],['monthly','Monthly · 12 checks'],['quarterly','Quarterly · 4 checks'],['annual','Annual · 1 check']],'biweekly')}${select('filingStatus','Filing status',[['single','Single'],['married','Married filing jointly']],'single')}${select('state','State (optional)',[['','No state tax'],['AL','Alabama'],['AK','Alaska'],['AZ','Arizona'],['AR','Arkansas'],['CA','California'],['CO','Colorado'],['CT','Connecticut'],['DE','Delaware'],['DC','District of Columbia'],['FL','Florida'],['GA','Georgia'],['HI','Hawaii'],['ID','Idaho'],['IL','Illinois'],['IN','Indiana'],['IA','Iowa'],['KS','Kansas'],['KY','Kentucky'],['LA','Louisiana'],['ME','Maine'],['MD','Maryland'],['MA','Massachusetts'],['MI','Michigan'],['MN','Minnesota'],['MS','Mississippi'],['MO','Missouri'],['MT','Montana'],['NE','Nebraska'],['NV','Nevada'],['NH','New Hampshire'],['NJ','New Jersey'],['NM','New Mexico'],['NY','New York'],['NC','North Carolina'],['ND','North Dakota'],['OH','Ohio'],['OK','Oklahoma'],['OR','Oregon'],['PA','Pennsylvania'],['RI','Rhode Island'],['SC','South Carolina'],['SD','South Dakota'],['TN','Tennessee'],['TX','Texas'],['UT','Utah'],['VT','Vermont'],['VA','Virginia'],['WA','Washington'],['WV','West Virginia'],['WI','Wisconsin'],['WY','Wyoming']],'')}</div></div><details class="advanced"><summary>Overtime & schedule ${icon('chevron',17)}</summary><div class="fields">${field('overtimeHours','Extra hours / week',0,{max:168,step:.5})}${field('multiplier','Overtime multiplier',1.5,{min:.01,step:.25,suffix:'×'})}${field('weeks','Paid weeks / year',52,{min:.01,max:52,step:1})}${field('bonus','Bonus this paycheck',0,{prefix:'$'})}</div><p class="caption">The gross check is an annual average. A one-off bonus is added only to this check.</p></details><details class="advanced"><summary>Optional deductions ${icon('chevron',17)}</summary><div class="fields">${field('preTax','Pre-tax deductions',0,{prefix:'$'})}${field('postTax','Post-tax deductions',0,{prefix:'$'})}${field('otherDeductions','Other deductions',0,{prefix:'$'})}</div><p class="caption">Enter amounts for one paycheck. Deductions are subtracted as entered. The take-home line below adds federal and FICA tax estimates; choose your state in the form to include a state tax estimate.</p></details>${formButtons('Calculate paycheck')}${regularFormFoot}</form>`;
 const panel=resultPanel('Your estimated paycheck','gross','/ check',[['regularPay','Regular pay'],['overtimePay','Overtime pay'],['bonus','Bonus this check'],['deductions','Entered deductions']],init,'<strong>Take-home estimate.</strong><br>Take-home = adjusted pay − estimated federal tax (2026 brackets, your filing status) − FICA − state tax when you choose a state. Local taxes, benefits, and exact W-4 withholding are excluded.','Biweekly · 26 checks/year').replace('<div class="result-note">',`<div class="adjusted-result"><span>Estimated pay after entered deductions</span><strong data-out="adjusted">${money(init.adjusted)}</strong></div><div class="adjusted-result"><span data-takehome-label>Estimated take-home · federal + FICA only</span><strong data-out="takeHome">${money(init.takeHome)}</strong></div><div class="pay-breakdown" data-breakdown>${payBar("Where this check goes",[["seg-takehome","Take-home",init.takeHome],["seg-federal","Federal tax",init.federalPerCheck],["seg-fica","FICA",init.ficaPerCheck],["seg-state","State tax",init.statePerCheck],["seg-deductions","Entered deductions",init.deductions]],init.gross)}</div><div class="result-note">`).replace('<span class="sr-only"',`${resultActions()}<span class="sr-only"`);
 return `<div class="tool-layout">${form}${panel}</div>`;
}
function raiseTool() {
 const init=raise({current:60000,next:66000,hours:8,days:5,weeks:52,mode:'annual'});
 return `<div class="tool-layout"><form class="card form-card sticky" data-calculator="raise" novalidate><div class="card-header"><h2>Compare your current & new pay</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div><div class="pay-top">${select('mode','Pay basis',[['annual','Annual salary'],['hourly','Hourly wage']],'annual')}</div><div class="fields form-section">${field('current','Current pay',60000,{prefix:'$',min:.01})}${field('next','New pay',66000,{prefix:'$'})}</div><div class="form-section">${select('raiseMode','Calculation mode',[['newPay','I know the new pay'],['percent','I know the raise %']],'newPay')}<div data-percent-mode hidden>${field('raisePercent','Raise %',10,{suffix:'%',step:.1})}</div></div><div class="form-section"><h3>Work schedule</h3><div class="fields">${field('hours','Hours / day',8,{max:24,min:.01})}${field('days','Days / week',5,{max:7,min:.01})}${field('weeks','Paid weeks / year',52,{max:52,min:.01})}</div></div><div class="form-actions">${calculateButton('Calculate pay change')}<button class="btn-secondary" type="reset">${icon('reset',15)} Reset</button></div>${regularFormFoot}</form>${resultPanel('Your annual pay change','annual','/ year',[['percent','Percentage change'],['monthly','Monthly change'],['weekly','Weekly change'],['hourly','Hourly change']],init,`<strong>${salaryHint}</strong><br>A negative change means lower pay. Weekly and hourly changes use the schedule you enter.`,'10.00% increase in pay').replace('<span class="sr-only"',`${resultActions()}<span class="sr-only"`)}</div>`;
}
function comparisonTool() {
 const a={salary:60000,bonus:2000,hours:40,pto:2,commute:5},b={salary:65000,bonus:0,hours:45,pto:3,commute:5},init=compare({a,b});
 const jobForm=(prefix,label,values)=>`<div class="card job-card"><div class="card-header"><h2 class="job-label">${label}</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div><div class="fields">${field(prefix+'Salary','Annual salary',values.salary,{prefix:'$'})}${field(prefix+'Bonus','Annual bonus',values.bonus,{prefix:'$'})}${field(prefix+'Hours','Work hours / week',values.hours,{max:168,min:.01})}${field(prefix+'Pto','Paid time off / year',values.pto,{suffix:'weeks',max:51.99})}${field(prefix+'Commute','Commute hours / week',values.commute,{max:168,helper:'Total round-trip time each week.'})}${field(prefix+'Match','401(k) employer match',values.match??0,{suffix:'%',max:100})}${field(prefix+'Health','Health premium you pay',values.health??0,{prefix:'$',suffix:'/ mo',helper:'Monthly premium deducted from your pay.'})}</div></div>`;
 return `<div class="comparison-layout"><form data-calculator="comparison" novalidate><div class="comparison-forms">${jobForm('a','JOB A',a)}${jobForm('b','JOB B',b)}</div><div class="form-actions" style="margin-top:20px">${calculateButton('Compare job offers')}<button class="btn-secondary" type="reset">${icon('reset',15)} Reset both jobs</button></div><div class="form-foot"><span>Use the same assumptions for both jobs.</span></div><div class="error" data-error role="alert"></div></form><aside class="result-card sticky compare-result" data-results aria-label="Comparison results"><h2>What each hour earns</h2><div class="job-result"><span class="result-label">Job A · effective hourly rate</span><strong class="result-value" data-out="aEffective">${money(init.a.effective)}</strong><div class="result-assumption" data-out="aHours">${init.a.committedHours.toLocaleString('en-US')} committed hours/year</div><div class="result-assumption" data-out="aTotal">${money(init.a.totalComp)} total compensation / year</div></div><div class="job-result"><span class="result-label">Job B · effective hourly rate</span><strong class="result-value" data-out="bEffective">${money(init.b.effective)}</strong><div class="result-assumption" data-out="bHours">${init.b.committedHours.toLocaleString('en-US')} committed hours/year</div><div class="result-assumption" data-out="bTotal">${money(init.b.totalComp)} total compensation / year</div></div><div class="comparison-diff" data-difference><strong>Job A earns ${money(init.difference)} more</strong> per hour of committed time.</div><p class="caption" style="color:#b6c3da;margin-top:17px">Salary + bonus + 401(k) match, minus health premiums, divided by work and commute time, excluding paid time off. Gross comparison. Taxes are excluded.</p>${resultActions()}<span class="sr-only" data-live aria-live="polite"></span></aside></div>`;
}
function freelanceTool() {
 const init=freelance({income:60000,expenses:6000,hours:25,weeks:48,tax:25,margin:10});
 return `<div class="tool-layout"><form class="card form-card sticky" data-calculator="freelance" novalidate><div class="card-header"><h2>Your income & business costs</h2><button class="text-button" type="reset">${icon('reset',13)} Reset</button></div>${field('income','Desired annual take-home income',60000,{prefix:'$',large:true})}<div class="form-section"><div class="fields">${field('hours','Billable hours / week',25,{min:.01,max:168})}${field('weeks','Billable weeks / year',48,{min:.01,max:52})}${field('expenses','Annual business expenses',6000,{prefix:'$'})}${field('tax','Tax reserve',25,{suffix:'%',max:99.99})}${field('margin','Profit margin on revenue',10,{suffix:'%',max:99.99})}</div><p class="caption">Billable hours exclude admin, marketing, and unpaid work. Tax reserve is your own planning assumption.</p></div><div class="form-actions">${formButtons('Calculate freelance rate')}</div>${regularFormFoot}</form>${resultPanel('Your target freelance rate','rate','/ hour',[['revenue','Required annual revenue'],['billableHours','Annual billable hours'],['reserve','Annual tax reserve'],['profit','Planned business profit'],['dayRate','Day rate (8 hours)']],init,'A planning estimate based on the reserve and margin you enter. This is not a tax calculation or guaranteed income. Expenses are added before the profit margin is applied.','25 billable hours/week · 48 weeks/year').replace('<span class="sr-only"',`${resultActions()}<span class="sr-only"`)}</div>`;
}
const toolInfo={
 'salary-to-hourly':{intro:'Turn an annual salary into an hourly rate. Adjust the schedule to match the hours that salary covers.',formula:'Annual salary ÷ (hours per week × paid weeks per year)',example:'$60,000 ÷ (40 × 52) = $28.85 an hour',text:'This gives an equivalent gross rate rather than a contractual hourly wage. Annual and monthly salary inputs stay fixed when unpaid weeks change. The hourly equivalent then changes because the same stated salary is spread across a different number of hours.',faq:[['Does an annual salary change if I enter unpaid weeks?','No. A stated annual salary is treated as the actual annual amount. Enter a reduced annual salary yourself if unpaid leave reduces your earnings. Unpaid weeks adjust the hours used to derive the equivalent hourly rate.'],['Is overtime included?','Only when you add overtime hours. Those hours are treated as extra compensation at the equivalent hourly rate times your selected multiplier. Use this only if that describes your pay arrangement.']]},
 'hourly-to-salary':{intro:'Convert your hourly rate into annual gross earnings and see the monthly, weekly, and daily equivalents.',formula:'Hourly rate × hours per week × paid weeks per year',example:'$25 × 40 × 52 = $52,000 per year',text:'Hourly pay changes with paid working time. The calculator subtracts unpaid weeks from the total weeks, then adds any overtime separately. Monthly and quarterly figures are annual averages.',faq:[['Do I subtract paid vacation?','No. If vacation replaces paid regular hours, it does not reduce your paid weeks in this earnings model. Subtract only time that is unpaid.'],['Why is monthly pay higher than four weekly checks?','A year has 52 weeks, so an average month contains about 4.33 weeks. Average monthly pay is annual earnings divided by 12, rather than weekly pay multiplied by four.']]},
 'paycheck':{intro:'Estimate gross and take-home pay for weekly, biweekly, semi-monthly, or monthly pay, with an optional state tax estimate.',formula:'Average gross paycheck = annual gross pay ÷ scheduled checks per year',example:'$52,000 ÷ 26 biweekly checks = $2,000 per check',text:'The paycheck headline shows an annual average using 52 weekly, 26 biweekly, 24 semi-monthly, or 12 monthly checks. With unpaid weeks, some actual checks may be smaller or zero. The conversion rows show a typical paid week and two-week period; those differ from an annual average when unpaid time is entered.',faq:[['Is this my take-home paycheck?','The take-home line is a federal-only estimate (2026 brackets + FICA for your filing status). State tax, benefits, and exact W-4 withholding are not included — use your pay statement for those amounts.'],['Why are biweekly and semi-monthly amounts different?','Biweekly pay usually means 26 checks a year. Semi-monthly pay means 24. The same annual gross income is divided into different numbers of checks.']]},
 'overtime':{intro:'Separate regular pay from overtime pay and see the weekly and annual totals.',formula:'Total weekly pay = (regular rate × regular hours) + (regular rate × multiplier × overtime hours)',example:'($25 × 40) + ($25 × 1.5 × 5) = $1,187.50 per week',text:'Enter regular hours and extra hours separately so each hour is counted once. The multiplier is a scenario input. The calculator does not determine which hours qualify for overtime or your legally required regular rate. Check the arrangement that applies to your role.',faq:[['How is time and a half calculated?','Multiply the regular hourly rate by 1.5. A $25 base rate becomes $37.50 per overtime hour. Five such hours add $187.50.'],['Does the tool automatically decide overtime eligibility?','No. It applies the multiplier to the overtime hours you enter. Eligibility and the regular rate used for payroll depend on the applicable rules and employment details.']]},
 'salary-increase':{intro:'See a pay change as a percentage and as an annual, monthly, weekly, or hourly amount.',formula:'Percentage change = (new pay − current pay) ÷ current pay × 100',example:'($66,000 − $60,000) ÷ $60,000 × 100 = 10%',text:'Use annual salary or hourly wage for both amounts. A lower new amount produces a negative percentage. Hourly and weekly equivalents depend on the work schedule and paid weeks you enter.',faq:[['Can I compare hourly wages?','Yes. Change the pay basis to hourly wage and enter both hourly amounts. The annual change uses your hours per day, days per week, and paid weeks per year.'],['Does a 10% raise mean 10% more take-home pay?','Not necessarily. The calculator shows the gross change. Taxes and deductions can affect the change in the amount deposited.']]},
 'salary-comparison':{intro:'Compare two jobs by salary, bonus, work hours, paid time off, and commute time.',formula:'Effective hourly rate = (salary + bonus) ÷ [(work hours + commute hours) × (52 − PTO weeks)]',example:'($60,000 + $2,000) ÷ [(40 + 5) × 50] = $27.56 per committed hour',text:'This personal time comparison excludes paid time off from time spent working and commuting while keeping annual compensation fixed. It is not a payroll rate. Insurance, retirement benefits, taxes, and nonfinancial factors are not assigned a value.',faq:[['What does committed time mean?','It means weekly work hours plus weekly commute hours over weeks actually worked. This model assumes no commute or work during the paid time off you enter.'],['Should I enter an expected bonus?','Use a realistic annual bonus. For uncertain bonuses, compare a conservative scenario and a higher one. Keep your assumptions consistent for both jobs.']]},
 'freelance-rate':{intro:'Estimate a billable rate that covers your income goal, business expenses, tax reserve, and profit margin.',formula:'Target revenue = [desired income ÷ (1 − tax reserve) + expenses] ÷ (1 − profit margin)',example:'[$60,000 ÷ 0.75 + $6,000] ÷ 0.90 ÷ 1,200 hours = $79.63/hour',text:'The model first increases the personal income target to allow for the chosen tax reserve. It then adds expenses and allows for profit as a share of revenue. Divide by billable hours per year to get the target hourly rate. The reserve is a planning assumption, not a calculation of actual tax liability.',faq:[['What counts as a billable hour?','An hour that a client pays for. Leave room for admin, proposals, marketing, and other work that does not generate a direct charge.'],['Is the tax reserve a tax estimate?','No. You enter your own reserve percentage. Actual tax depends on your circumstances and jurisdiction. The tool does not calculate it.']]}
};

const receiptHtml=`<details class="calc-receipt" open><summary>Calculation receipt: inputs, formula, and result</summary><div data-receipt><p class="caption">Enter values above to see the receipt.</p></div></details>`;
const conventionsHtml=`<section class="article-section calc-conventions"><h2>Why calculators can show different results</h2><div class="card method-card"><span class="icon">${icon('info',21)}</span><div><h3>Same question, different assumptions</h3><ul><li><strong>Your schedule matters:</strong> results use the hours and paid weeks you enter — a 2,080-hour year (40 × 52) is only the default, not your schedule.</li><li><strong>Gross, not net:</strong> these tools show pay before income tax, Social Security, Medicare, and benefit deductions.</li><li><strong>Rules vary:</strong> overtime eligibility, the regular rate, and state rules are not decided by the calculator — they come from your pay arrangement.</li><li><strong>Averages, not checks:</strong> monthly and semi-monthly figures are annual averages (annual ÷ 12 or ÷ 24), not four weekly checks added together.</li></ul></div></div></section>`;
