 let notes=`<div class="content-layout">${toc('About this calculation',[['formula','The formula'],['assumptions','What to keep in mind'],['tool-faqs','Common questions'],['related','Related calculators']])}<div><section class="article-section" id="formula"><h2>How to calculate it</h2><div class="formula-card"><div class="formula">${info.formula}</div><p class="example">${info.example}</p></div></section><section class="article-section" id="assumptions"><h2>Know what the result includes</h2><div class="card method-card"><span class="icon">${icon('info',21)}</span><div><h3>Use the right assumptions</h3><p>${info.text}</p></div></div></section><section class="article-section" id="tool-faqs"><h2>Frequently asked questions</h2>${faqHtml(info.faq)}</section><section class="article-section" id="related"><h2 style="margin-bottom:16px">Related calculators</h2><div class="tool-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${toolCards(tools.filter(x=>x.slug!==t.slug).slice(0,2))}</div></section></div></div>`;
 if(core.tools[t.slug])notes=core.tools[t.slug].body;
 const intro=core.tools[t.slug]?.intro||info.intro;
